for(var number,assert=console.assert,unique=require("array-unique"),random=require("./"),iterations=1e4,cache=[],i=0;i<iterations;i++){if((number=random())<0){assert(!1,"Random numbers should be greater than or equal to zero");break}if(number>=1){assert(!1,"Random numbers should be less than one");break}cache.push(number)}assert(unique(cache).length===iterations,"Random numbers should be unique");